import sys

k = int(sys.stdin.read().split()[0])
fib = [1, 2]
while fib[-1] + fib[-2] <= k:
    fib.append(fib[-1] + fib[-2])
if k <= 20000:
    INF = 10 ** 9
    dp = [0] + [INF] * k
    for v in range(1, k + 1):
        for f in fib:
            if f > v:
                break
            if dp[v - f] + 1 < dp[v]:
                dp[v] = dp[v - f] + 1
    print(dp[k])
else:
    # too large for the table: greedy from the largest term
    cnt = 0
    for f in reversed(fib):
        while k >= f:
            k -= f
            cnt += 1
    print(cnt)

